1	<!doctype html>
2	<html><head><meta charset="utf-8"><title>Screen 05 full track test</title>
3	<style>
4	html,body{margin:0;background:#000;overflow:hidden;font-family:system-ui,sans-serif}canvas{display:block}
5	#hud{position:fixed;left:0;right:0;top:10px;display:flex;flex-direction:column;align-items:center;gap:8px;pointer-events:none}
6	.bar{display:flex;gap:28px;align-items:center;background:linear-gradient(#7b2bbf,#4a1386);border:2px solid #d9a7ff;border-radius:30px;padding:6px 22px;color:#fff;font-weight:800;font-size:22px;box-shadow:0 2px 8px #0006}
7	.title{background:#5a1aa0e0;border:2px solid #f2c14e;border-radius:20px;padding:4px 18px;color:#fff;font-weight:800;font-style:italic;font-size:17px;letter-spacing:.5px}
8	</style>
9	<script type="importmap">{"imports":{"three":"./node_modules/three/build/three.module.js","three/addons/":"./node_modules/three/examples/jsm/","@sparkjsdev/spark":"./node_modules/@sparkjsdev/spark/dist/spark.module.js"}}</script>
10	</head><body>
11	<div id="hud"><div class="bar"><span>&#10084;&#65039; 5/5</span><span id="coins">&#129689; 1,420</span></div><div class="title">05 &middot; FLOW INTO THE CURRENT</div></div>
12	<script type="module">
13	import * as THREE from 'three';
14	import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
15	import { SplatMesh, SparkRenderer } from '@sparkjsdev/spark';
16	const q = new URLSearchParams(location.search);
17	const W = +(q.get('w') ?? 540), H = +(q.get('h') ?? 960);
18	const renderer = new THREE.WebGLRenderer({ antialias: true, preserveDrawingBuffer: true });
19	renderer.setPixelRatio(1); renderer.setSize(W, H); document.body.appendChild(renderer.domElement);
20	renderer.toneMapping = THREE.NeutralToneMapping; renderer.toneMappingExposure = 0.86;
21	const SC = await (await fetch('scene05.json')).json();
22	const TR = await (await fetch('track.json')).json();
23	const scene = new THREE.Scene();
24	const camera = new THREE.PerspectiveCamera(SC.cam.fov, W / H, 0.01, 200);
25	const spark = new SparkRenderer({ renderer }); scene.add(spark);
26	const flip = (m) => { m.quaternion.set(1, 0, 0, 0); return m; };
27	
28	// ---------- track: start piece, alternating sharp sections (bay / mirrored bay), light sections far away, tunnel end ----------
29	const near = flip(new SplatMesh({ url: 'near.ply' })); scene.add(near);
30	const far = flip(new SplatMesh({ url: 'far.ply' })); scene.add(far);
31	const src = { hi: new SplatMesh({ url: 'bay.ply' }), him: new SplatMesh({ url: 'bay_m.ply' }), lo: new SplatMesh({ url: 'bay_lo.ply' }), lom: new SplatMesh({ url: 'bay_m_lo.ply' }) };
32	await Promise.all([near.initialized, far.initialized, ...Object.values(src).map((m) => m.initialized)]);
33	const DV = new THREE.Vector3(...TR.D), AX = new THREE.Vector3(...TR.ax), N = new THREE.Vector3(...TR.n), DU = DV.dot(AX);
34	const tiles = [];
35	for (let k = 1; k <= TR.N; k++) {
36	  const mir = q.get('nomirror') ? false : k % 2 === 1;
37	  const hi = flip(new SplatMesh({ packedSplats: (mir ? src.him : src.hi).packedSplats })), lo = flip(new SplatMesh({ packedSplats: (mir ? src.lom : src.lo).packedSplats }));
38	  for (const m of [hi, lo]) { m.position.set(...TR.offsets[k - 1]); m.visible = false; scene.add(m); }
39	  tiles.push({ k, hi, lo });
40	}
41	let kcNow = -99;
42	const showTrack = (uB) => {
43	  const kc = Math.floor((uB - TR.UA) / DU); if (kc === kcNow) return; kcNow = kc;
44	  near.visible = kc <= 1;
45	  for (const t of tiles) { t.hi.visible = t.k >= kc - 1 && t.k <= kc + 1; t.lo.visible = t.k >= kc + 2 && t.k <= kc + 5; }
46	  const last = Math.min(TR.N, Math.max(1, kc + 5)); far.position.set(...TR.far_offsets[last]); far.visible = true;
47	};
48	
49	// ---------- Benny's path ----------
50	const T = TR.trail.map((p) => new THREE.Vector3(...p)), TS = TR.trail_s;
51	const at = (s, out) => { s = Math.max(0, Math.min(TS[TS.length - 1], s)); let lo = 0, hi = TS.length - 1; while (hi - lo > 1) { const m = (lo + hi) >> 1; if (TS[m] < s) lo = m; else hi = m; } const k = (s - TS[lo]) / Math.max(1e-6, TS[hi] - TS[lo]); return out.lerpVectors(T[lo], T[hi], k); };
52	const a = new THREE.Vector3(), b = new THREE.Vector3();
53	const frameAt = (s, win = 0.35) => { at(s - win * 0.3, a); at(s + win, b); const t = b.sub(a).normalize().clone(); const n = N.clone().addScaledVector(t, -t.dot(N)).normalize(); const r = new THREE.Vector3().crossVectors(t, n).normalize(); return { t, r, n }; };
54	const basis = (F) => new THREE.Matrix4().makeBasis(F.r.clone().negate(), F.n, F.t);
55	
56	// ---------- Benny (the improved 3D Benny: mesh, bake and paddling shader as in the game) ----------
57	const VERT_HEAD = `uniform float uT; uniform float uSwim; uniform vec2 uPom;
58	vec3 b31rot(vec3 r, vec3 ax, float a){ float c = cos(a), s = sin(a); return r * c + cross(ax, r) * s + ax * dot(ax, r) * (1.0 - c); }`;
59	const VERT_BODY = `vec3 p = position;
60	float side = p.x >= 0.0 ? 1.0 : -1.0;
61	float wa = smoothstep(0.30, 0.37, abs(p.x)) * (1.0 - smoothstep(0.08, 0.16, abs(p.y + 0.18)));
62	float ph = uT * 7.5 + (side > 0.0 ? 0.0 : 3.14159);
63	vec3 piv = vec3(side * 0.31, -0.18, 0.0);
64	vec3 q = p - piv;
65	q = b31rot(q, vec3(0.0, 0.0, 1.0), side * uSwim * wa * 0.42 * sin(ph));
66	q = b31rot(q, vec3(0.0, 1.0, 0.0), side * uSwim * wa * 0.5 * cos(ph));
67	p = piv + q;
68	float wp = smoothstep(0.17, 0.27, p.y);
69	vec3 pp = vec3(0.0, 0.19, 0.05);
70	vec3 r = p - pp;
71	r = b31rot(r, vec3(1.0, 0.0, 0.0), uPom.x * wp);
72	r = b31rot(r, vec3(0.0, 0.0, 1.0), uPom.y * wp);
73	p = pp + r;
74	float sq = 1.0 + 0.03 * uSwim * sin(uT * 15.0);
75	p.y = (p.y + 0.5) * sq - 0.5; p.xz /= sqrt(sq);
76	vec3 transformed = p;`;
77	const gltf = await new GLTFLoader().loadAsync('benny31.glb');
78	const map = await new THREE.TextureLoader().loadAsync('bake.png'); map.colorSpace = THREE.SRGBColorSpace; map.flipY = false; map.anisotropy = 8;
79	let geo = null; gltf.scene.traverse((o) => { if (o.isMesh && !geo) geo = o.geometry; });
80	const U = { uT: { value: 0 }, uSwim: { value: 1 }, uPom: { value: new THREE.Vector2() } };
81	const bmat = new THREE.MeshBasicMaterial({ map, color: new THREE.Color(4, 4, 4) });
82	bmat.onBeforeCompile = (sh) => {
83	  Object.assign(sh.uniforms, U);
84	  sh.vertexShader = sh.vertexShader.replace('#include <common>', '#include <common>\n' + VERT_HEAD).replace('#include <begin_vertex>', VERT_BODY);
85	  sh.fragmentShader = sh.fragmentShader.replace('#include <colorspace_fragment>', `#include <colorspace_fragment>
86	    { vec3 col = gl_FragColor.rgb; float l = dot(col, vec3(0.2126, 0.7152, 0.0722)); col = mix(vec3(l), col, 1.36); col = (col - 0.5) * 1.15 + 0.5; gl_FragColor.rgb = clamp(col, 0.0, 1.0); }`);
87	};
88	const bmesh = new THREE.Mesh(geo, bmat); bmesh.frustumCulled = false;
89	const KH = 0.9 * SC.benny_h / (0.99 * 0.78); // the painted Benny's size: ~22 % of him under the water line
90	const holder = new THREE.Group(); holder.rotation.y = Math.PI; holder.scale.setScalar(KH); holder.position.y = 0.496 * KH - 0.22 * 0.99 * KH;
91	holder.add(bmesh);
92	const benny = new THREE.Group(); benny.add(holder); scene.add(benny);
93	const pxW = SC.benny_h / 400; // painted px -> world near Benny (the painted Benny is ~400 px from pom-pom to water)
94	
95	// ---------- water life: his painted splash, flowing glints, bubbles ----------
96	const tl = new THREE.TextureLoader();
97	const splashTex = await tl.loadAsync('splash.png'); splashTex.colorSpace = THREE.SRGBColorSpace;
98	const splash = new THREE.Sprite(new THREE.SpriteMaterial({ map: splashTex, toneMapped: false, transparent: true, depthWrite: false }));
99	splash.renderOrder = 5; scene.add(splash);
100	const glintTex = await tl.loadAsync('glint.png');
101	const NG = 320, gS = new Float32Array(NG), gL = new Float32Array(NG), gP = new Float32Array(NG), gSz = new Float32Array(NG);
102	const gPos = new Float32Array(NG * 3), gAlpha = new Float32Array(NG), gSize = new Float32Array(NG);
103	const rnd = (() => { let x = 12345; return () => ((x = (x * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff); })();
104	for (let i = 0; i < NG; i++) { gS[i] = rnd() * 7.5 - 1.0; gL[i] = (rnd() * 2 - 1) * 0.62; gP[i] = rnd() * 6.28; gSz[i] = 0.5 + rnd(); }
105	const gGeo = new THREE.BufferGeometry(); gGeo.setAttribute('position', new THREE.BufferAttribute(gPos, 3)); gGeo.setAttribute('aAlpha', new THREE.BufferAttribute(gAlpha, 1)); gGeo.setAttribute('aSize', new THREE.BufferAttribute(gSize, 1));
106	const gMat = new THREE.ShaderMaterial({
107	  uniforms: { map: { value: glintTex }, scale: { value: H * 0.5 } },
108	  vertexShader: `attribute float aAlpha; attribute float aSize; varying float vA; uniform float scale;
109	    void main(){ vA = aAlpha; vec4 mv = modelViewMatrix * vec4(position, 1.0); gl_PointSize = aSize * scale / -mv.z; gl_Position = projectionMatrix * mv; }`,
110	  fragmentShader: `uniform sampler2D map; varying float vA; void main(){ vec4 c = texture2D(map, gl_PointCoord); gl_FragColor = vec4(vec3(0.85, 0.97, 1.0) * c.r, c.r * vA); }`,
111	  transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, toneMapped: false,
112	});
113	const glints = new THREE.Points(gGeo, gMat); glints.frustumCulled = false; glints.renderOrder = 6; scene.add(glints);
114	const bubTex = await tl.loadAsync('bubble.png'); bubTex.colorSpace = THREE.SRGBColorSpace;
115	const bubbles = [];
116	for (let i = 0; i < 46; i++) { const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: bubTex, toneMapped: false, transparent: true, depthWrite: false, opacity: 0.85 })); sp.renderOrder = 7; scene.add(sp); bubbles.push({ sp, s: rnd() * 7.5 - 1.0, lat: (rnd() < 0.5 ? -1 : 1) * (0.45 + rnd() * 0.4), hgt: 0.02 + rnd() * 0.14, size: 0.022 + rnd() * 0.05, ph: rnd() * 6.28 }); }
117	
118	// ---------- coins ----------
119	const ctex = await tl.loadAsync('coin.png'); ctex.colorSpace = THREE.SRGBColorSpace;
120	const coins = [];
121	for (let i = 0; i < 40; i++) {
122	  const s = 0.45 + i * 0.32; const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: ctex, toneMapped: false, transparent: true, alphaTest: 0.35, depthWrite: false }));
123	  const d = SC.coin_d; sp.scale.set(d * 1.15, d * 1.15, 1); at(s, sp.position).addScaledVector(frameAt(s).n, d * 0.75); sp.renderOrder = 10; scene.add(sp); coins.push({ s, lat: 0, sp, got: -1 });
124	}
125	let coinCount = 1420; const coinEl = document.getElementById('coins');
126	
127	// ---------- follow camera: at the start exactly the approved picture's camera, then the same relation to Benny ----------
128	const camFwd = new THREE.Vector3(...SC.cam.fwd), camUp = new THREE.Vector3(...SC.cam.up);
129	const camQ0 = new THREE.Quaternion().setFromRotationMatrix(new THREE.Matrix4().lookAt(new THREE.Vector3(), camFwd, camUp));
130	const M0 = basis(frameAt(0));
131	const relPos = new THREE.Vector3().sub(T[0]).applyMatrix4(new THREE.Matrix4().copy(M0).transpose());
132	const relQ = new THREE.Quaternion().setFromRotationMatrix(M0).invert().multiply(camQ0);
133	const st = { s: 0, lat: 0, vlat: 0, camLat: 0, lean: 0, camF: null };
134	const tmp = new THREE.Vector3(), tmp2 = new THREE.Vector3(), Z = new THREE.Vector3(0, 0, 1);
135	window.step = (t, dt, steer, speed) => {
136	  st.s += speed * dt;
137	  st.vlat += (steer * 0.45 - st.vlat) * Math.min(1, dt * 8); st.lat = THREE.MathUtils.clamp(st.lat + st.vlat * dt, -0.3, 0.3);
138	  const F = frameAt(st.s); const M = basis(F);
139	  // lean into the river's bends (curvature) and into his own steering
140	  const Fa = frameAt(st.s + 0.4); const turn = F.t.clone().cross(Fa.t).dot(F.n);
141	  st.lean += ((-steer * 0.22 - turn * 2.2) - st.lean) * Math.min(1, dt * 5);
142	  at(st.s, tmp).addScaledVector(F.r, st.lat);
143	  showTrack(tmp.dot(AX));
144	  benny.position.copy(tmp).addScaledVector(F.n, Math.sin(t * Math.PI * 1.6) * 0.006);
145	  benny.quaternion.setFromRotationMatrix(M).multiply(new THREE.Quaternion().setFromAxisAngle(Z, st.lean));
146	  U.uT.value = t; U.uSwim.value = 1; U.uPom.value.set(Math.sin(t * 5.0) * 0.06 + steer * 0.1, steer * 0.18 + st.lean * 0.4);
147	  // painted splash around his waist, travelling with him, wobbling
148	  splash.position.copy(benny.position).addScaledVector(F.t, 0.05).addScaledVector(F.n, -0.01 - 23 * pxW * 0.5);
149	  splash.scale.set(799 * pxW * 0.8 * (1 + 0.04 * Math.sin(t * 9)), 309 * pxW * 0.8 * (1 + 0.06 * Math.sin(t * 7 + 1)), 1);
150	  splash.material.rotation = -st.lean * 0.6;
151	  // flowing glints: fixed on the river surface, sliding toward the camera with the current, twinkling
152	  for (let i = 0; i < NG; i++) {
153	    gS[i] -= 0.55 * dt; if (gS[i] < st.s - 1.4) gS[i] += 8.5; if (gS[i] > st.s + 7.1) gS[i] -= 8.5;
154	    const Fg = frameAt(gS[i], 0.2); at(gS[i], tmp2).addScaledVector(Fg.r, gL[i]).addScaledVector(Fg.n, 0.012);
155	    gPos.set([tmp2.x, tmp2.y, tmp2.z], i * 3);
156	    const tw = Math.max(0, Math.sin(t * 6 + gP[i])); gAlpha[i] = tw * tw * 0.9 * THREE.MathUtils.smoothstep(st.s - 1.4, st.s - 0.6, gS[i]);
157	    gSize[i] = 0.035 * gSz[i] * (0.6 + tw);
158	  }
159	  gGeo.attributes.position.needsUpdate = true; gGeo.attributes.aAlpha.needsUpdate = true; gGeo.attributes.aSize.needsUpdate = true;
160	  for (const bb of bubbles) {
161	    bb.s -= 0.35 * dt; if (bb.s < st.s - 1.4) bb.s += 8.5;
162	    const Fb = frameAt(bb.s, 0.2); at(bb.s, bb.sp.position).addScaledVector(Fb.r, bb.lat).addScaledVector(Fb.n, bb.hgt + 0.02 * Math.sin(t * 2 + bb.ph));
163	    const z = bb.size * (1 + 0.05 * Math.sin(t * 3 + bb.ph)); bb.sp.scale.set(z, z, 1);
164	  }
165	  // follow camera; steering followed by half, gently smoothed
166	  st.camLat += (st.lat * 0.5 - st.camLat) * Math.min(1, dt * 4);
167	  const Fc = frameAt(st.s, 0.9); const Mc = basis(Fc);
168	  camera.position.copy(relPos).applyMatrix4(Mc).add(at(st.s, tmp)).addScaledVector(Fc.r, st.camLat);
169	  camera.quaternion.setFromRotationMatrix(Mc).multiply(relQ).multiply(new THREE.Quaternion().setFromAxisAngle(Z, st.lean * 0.12)); camera.updateMatrixWorld();
170	  for (const c of coins) {
171	    if (c.got < 0 && st.s >= c.s && Math.abs(st.lat - c.lat) < 0.14) { c.got = t; coinCount += 10; coinEl.textContent = '\u{1FA99} ' + coinCount.toLocaleString('en-US'); }
172	    if (c.got >= 0) { const k = (t - c.got) / 0.4; c.sp.visible = k < 1; if (k < 1) { c.sp.position.copy(benny.position).addScaledVector(F.n, SC.benny_h * (1.05 + 0.6 * k)); c.sp.material.opacity = 1 - k * k; const d = SC.coin_d * 0.7 * (1 - 0.5 * k); c.sp.scale.set(d, d, 1); } }
173	  }
174	  return { s: +st.s.toFixed(3), lat: +st.lat.toFixed(3), coins: coinCount, tile: kcNow };
175	};
176	window.renderNow = async (n = 2) => { for (let i = 0; i < n; i++) { renderer.render(scene, camera); await new Promise((r) => setTimeout(r, 60)); } renderer.render(scene, camera); return true; };
177	window.step(0, 0, 0, 0);
178	for (let i = 0; i < 6; i++) { renderer.render(scene, camera); await new Promise((r) => setTimeout(r, 150)); }
179	window.ready = true;
180	</script></body></html>
181

1	// Uninterrupted normal-speed run through the whole Screen 05 track (deterministic 30 fps steps), frames -> mp4
2	const { chromium } = require('playwright'); const { spawn, execFileSync } = require('child_process'); const fs = require('fs');
3	(async () => {
4	  const [out, secs = '7.6', speed = '1.4', w = '480', h = '854'] = process.argv.slice(2); fs.mkdirSync(out, { recursive: true });
5	  const port = 8700 + Math.floor(Math.random() * 200);
6	  const srv = spawn('python3', ['-m', 'http.server', String(port)], { cwd: __dirname, stdio: 'ignore' });
7	  await new Promise((r) => setTimeout(r, 1200));
8	  const browser = await chromium.launch({ args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist'] });
9	  const log = [];
10	  try {
11	    const page = await browser.newPage({ viewport: { width: +w, height: +h }, deviceScaleFactor: 1 });
12	    page.on('pageerror', (e) => console.log('pageerror:', String(e).slice(0, 300)));
13	    await page.goto(`http://127.0.0.1:${port}/play3.html?w=${w}&h=${h}`);
14	    await page.waitForFunction(() => window.ready === true, null, { timeout: 900000 });
15	    const fps = 30, n = Math.round(+secs * fps);
16	    for (let i = 0; i < n; i++) {
17	      const t = i / fps;
18	      const steer = t > 0.8 && t < 6.8 ? Math.sin((t - 0.8) * 1.9) * 0.75 : 0;
19	      const o = await page.evaluate(([t, dt, st, sp]) => window.step(t, dt, st, sp), [t, i === 0 ? 0 : 1 / fps, steer, +speed]);
20	      await page.evaluate(() => window.renderNow(1));
21	      await page.screenshot({ path: `${out}/f_${String(i).padStart(4, '0')}.jpg`, type: 'jpeg', quality: 92, timeout: 600000 });
22	      log.push({ i, t: +t.toFixed(3), steer: +steer.toFixed(3), ...o });
23	      if (i % 10 === 0) { console.log('frame', i, '/', n, JSON.stringify(o), new Date().toISOString().slice(11, 19)); fs.writeFileSync(`${out}/clip_log.json`, JSON.stringify(log)); }
24	    }
25	    fs.writeFileSync(`${out}/clip_log.json`, JSON.stringify(log, null, 1));
26	    execFileSync('ffmpeg', ['-y', '-loglevel', 'error', '-framerate', String(fps), '-i', `${out}/f_%04d.jpg`, '-c:v', 'libx264', '-pix_fmt', 'yuv420p', '-crf', '20', `${out}/screen05_full_run.mp4`]);
27	    console.log('done', n, 'frames');
28	  } finally { await browser.close(); srv.kill(); }
29	})();
